window.__saqPaperQuestions("2019-1-pah",[{"number":1,"title":"","stemText":"A 28 year old man has presented to the ED after falling 2 metres from a ladder landing on to his head. As part of his assessment, a CT scan of his cervical spine was performed. One image from this scan is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the diagnosis, supported by 3 abnormalities on the CT scan. (4 marks) Diagnosis Radiological abnormalities There are no other injuries."},{"id":"b","label":"Part B","prompt":"List 5 key features of your examination. For each, state the clinical relevance. (10 marks) Examination feature Clinical relevance"},{"id":"c","label":"Part C","prompt":"Complete the table by listing the appropriate spinal cord levels as per the ASIA classification standard. (4 marks)"}],"propPages":["asset:img43119467e25b202a96"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>13/17</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">dislocation C4 on 5</div><div class=\"answer-line\">Anterolisthesis C4 on 5 approx 25%</div><div class=\"answer-line\">Widening of interspinous space (or loss of continuity at ligamentum flavum)</div><div class=\"answer-line\">Loss of any of the spinal ‘lines’</div><div class=\"answer-line\">Significant Anterior soft tissue swelling at C4/5</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Neurologic status - * - conscious state, signs of anterior or posterior cerebral ischaemia carotid</td><td>or vertebral dissection</td></tr><tr><td>Neurologic status - UL neurologic exam weakness from cord injury/haematoma</td><td><strong>Cardiovascular status – risk of neurogenic shock – hypotension with vasodilation </strong></td></tr><tr><td>Priapism – evidence of major cord injury</td><td>Bulbocavernosus reflex – absence suggests spinal shock. Presence allows classification of cord</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">2.</div><div class=\"answer-line\"><strong>Respiratory status (accept oxygenation or ventilation or testing (spirometry, FEV1) </strong><strong> </strong></div><div class=\"answer-line\"><strong>respiratory insufficiency secondary to loss of diaphragmatic innervation) </strong></div><div class=\"answer-line\">Neurologic status - * - conscious state, signs of anterior or posterior cerebral ischaemia carotid</div><div class=\"answer-line\">or vertebral dissection</div><div class=\"answer-line\">Neurologic status - UL neurologic exam weakness from cord injury/haematoma</div><div class=\"answer-line\"><strong>Cardiovascular status – risk of neurogenic shock – hypotension with vasodilation </strong></div><div class=\"answer-line\">Priapism – evidence of major cord injury</div><div class=\"answer-line\">Bulbocavernosus reflex – absence suggests spinal shock. Presence allows classification of cord</div><div class=\"answer-line\">injury severity (ie ASIA status – complete vs incomplete)</div><div class=\"answer-line\">Elbow flexors – C5</div><div class=\"answer-line\">Elbow extensors – C7</div><div class=\"answer-line\">Knee extensors – L 3</div><div class=\"answer-line\">Ankle plantar flexors: - S1</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"You are working in a metropolitan ED without an obstetric service on site. A 19 year old woman has presented to the ED with abdominal pain. She is 29 weeks pregnant.","parts":[{"id":"a","label":"Part A","prompt":"List 5 features of your history or examination that would suggest premature labour.\n(5 marks)"},{"id":"b","label":"Part B","prompt":"List 2 investigations that would provide further evidence of premature labour. (2 marks)\nYour assessment is consistent with premature labour."},{"id":"c","label":"Part C","prompt":"State 5 steps in your management of this patient. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Rupture of membranes – pooling amniotic fluid in vagina or history sudden gush fluid</div><div class=\"answer-line\">Regular contractions- progressive intensity</div><div class=\"answer-line\">Increasing low back/pelvic pain</div><div class=\"answer-line\">Cervical dilatation/shortening</div><div class=\"answer-line\">Fetal descent into pelvis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">CTG trace showing regular contractions</div><div class=\"answer-line\">Ferning of amniotic fluid on microscopy</div><div class=\"answer-line\">Vaginal fluid pH &gt;6.5</div><div class=\"answer-line\">Fetal Fibronectin level</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Steroids: betamethasone IM 11.4mg</div><div class=\"answer-line\">Antibiotics – Amp/Gent/Flagyl</div><div class=\"answer-line\">Neuroprotection: MgSO4 4gm over 20min</div><div class=\"answer-line\"><strong>Transfer to obstetric centre </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 26 year old woman has been brought to the ED after being found unconscious in her bed at home.\nShe has not been seen for 2 days.\nHer blood chemistry is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the main abnormality related to the Na, K, Cl and HCO3 results. Include your justification and the most likely cause of the abnormality. (3 marks) Main abnormality Justification Most likely cause"},{"id":"b","label":"Part B","prompt":"State the main abnormality related to the urea and creatinine results. Include your justification and the most likely cause of the abnormality. (3 marks) Main abnormality Justification Most likely cause"},{"id":"c","label":"Part C","prompt":"State the main abnormality related to the total protein, albumin and globulin results. Include your justification and the most likely cause of the abnormality. (3 marks) Main abnormality Justification Most likely cause"},{"id":"d","label":"Part D","prompt":"State the main abnormality related to the liver function test results. Include your justification and the most likely cause of the abnormality. (3 marks) Main abnormality Justification Most likely cause"},{"id":"e","label":"Part E","prompt":"List 3 further tests you would perform to determine the cause of the overall clinical\npicture. For each, state how the test will be useful. (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"}],"propPages":["asset:imgd119418e2d3b115d12"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/15</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Justification: AG = 135 – (102) = 33</div><div class=\"answer-line\">Most likely cause: Lactate (liver failure – impaired Cori cycle) or toxins</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">2.</div><div class=\"answer-line\">Main abnormality: acute renal failure (intrinsic)</div><div class=\"answer-line\">Justification: urea: creat ratio &lt;100</div><div class=\"answer-line\">Most likely cause: hepatorenal syndrome or toxins (CK, Mb etc)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Main abnormality: Synthetic liver failure</div><div class=\"answer-line\">Justification: Albumin and globulin both decreased</div><div class=\"answer-line\">Most likely cause: Acute fulminant liver failure</div><div class=\"answer-line\">4.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Main abnormality: Acute severe hepatitis</div><div class=\"answer-line\">Justification: ALT/AST elevated &gt;&gt; membrane bound enzymes (GGT/ALP)</div><div class=\"answer-line\">Most likely cause: Toxic hepatitis (paracetamol toxicity)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Hepatic USS – Excludes structural cause ie CBD obstruction, PSC</td><td>Hepatitis serology</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 67 year old man has presented with severe central chest pain radiating to his back. You are concerned that he has an aortic dissection.","parts":[{"id":"a","label":"Part A","prompt":"List 4 risk factors for aortic dissection. (4 marks)"},{"id":"b","label":"Part B","prompt":"Describe the Stanford classification system for aortic dissection. (2 marks) The patient has a confirmed proximal aortic dissection on CT angiogram of the chest.\nHis vital signs are:\n\nGCS\nPulse /min\n\nBP\n180/95 mmHg"},{"id":"c","label":"Part C","prompt":"State 4 steps in your management of this patient. Include drug doses and end-points\nwhere appropriate. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ Shortly after returning from the CT scanner, the patient develops hypotension."},{"id":"d","label":"Part D","prompt":"List 3 likely causes for the patient’s hypotension. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Connective Tissue disease – ie Ehlers Danlos</div><div class=\"answer-line\">Hypertension</div><div class=\"answer-line\">Bicuspid aortic valves</div><div class=\"answer-line\">Coarctation of the Aorta</div><div class=\"answer-line\">Pre-existing aneurysmal dilatation</div><div class=\"answer-line\">Old</div><div class=\"answer-line\">Male</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Stanford A: involves ascending aorta</div><div class=\"answer-line\">Stanford B: involves ONLY descending aorta (ie distal to left subclavian)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – titrated fentanyl 25mcg IV to comfort</div><div class=\"answer-line\">Slow HR – IV B-blocker – esmolol or metoprolol 2.5mg repeat to HR &lt;60</div><div class=\"answer-line\">Blood pressure Control – GTN/Hydralazine once HR slow to BP &lt;110mmHg</div><div class=\"answer-line\"><strong>Immediate CTS attendance for definitive Rx in theatre </strong></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Aortic Incompetence from aortic root dissection</div><div class=\"answer-line\">Tamponade from pericardial extension</div><div class=\"answer-line\">Iatrogenesis from excess BP/HR management</div><div class=\"answer-line\">Branch vessel dissection – pseudohypotension (ie brachial artery involvement</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 10 month old boy has been brought to the ED by his mother. She is concerned that he has been crying and not using his left arm. An x-ray has been performed due to apparent arm tenderness on examination. The x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Describe the abnormalities on the x-ray. Include your clinical impression. (3 marks)"},{"id":"b","label":"Part B","prompt":"State 3 components of your examination of this child. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"State 4 components of your management of this child. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":["asset:imga3582099b3a2848323"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Spiral fracture of left humerus (diaphysis)</div><div class=\"answer-line\"><strong>Fracture consistent with physical child abuse</strong>; inconsistent with age</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Thorough exam for other signs of abuse/neglect (max 2 marks for other signs abuse)</td></tr><tr><td>-</td><td>Other fractures</td></tr><tr><td>-</td><td>Burns</td></tr><tr><td>-</td><td>Bruising/bite marks</td></tr><tr><td colspan=\"2\">Developmental assessment for growth retardation and developmental milestones</td></tr><tr><td colspan=\"2\">Exam for other features of primary bone disorders/renal disease</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – paracetamol 15mg/kg, ibuprofen 10mg/kg</div><div class=\"answer-line\">Immobilisation in plaster (given age)</div><div class=\"answer-line\">Admission for further investigation of fracture and social circumstances</div><div class=\"answer-line\"><strong>Notification of child protection authorities </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 25 year old man has presented with 2 days of fever, dysuria and right sided back pain. He has no\n• ther medical problems.\nOn arrival, his vital signs are: Temperature 39.0 degrees Pulse 125 /min\n\nBP\n90/60 mmHg Your provisional diagnosis is right sided pyelonephritis.","parts":[{"id":"a","label":"Part A","prompt":"State 3 steps in your initial management of this man. Include doses and end-points where\nappropriate. (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List 3 likely bacterial pathogens that could cause this man’s illness. (3 marks)"},{"id":"c","label":"Part C","prompt":"List and justify 4 investigations you would perform. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Fluids: 20mls/kg crystalloid; aim MAP &gt;65 or SBP &gt;100</div><div class=\"answer-line\">Analgesia: Morphine 2.5mg IV repeated to comfort</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">E. Coli</div><div class=\"answer-line\">Klebsiella</div><div class=\"answer-line\">Proteus Mirabilis</div><div class=\"answer-line\">Pseudomonas</div><div class=\"answer-line\">Enterococci</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Urine micro – confirm UTI</div><div class=\"answer-line\">Urine Culture – guide subsequent Ab therapy</div><div class=\"answer-line\">Renal tract imaging (USS renal tracts) for structural abnormality given unusual demographic for</div><div class=\"answer-line\">pyelo (male)</div><div class=\"answer-line\">Chem20 to exclude renal impairment to guide gentamicin dosing</div><div class=\"answer-line\">Blood Cultures – evidence of sepsis – will confirm bacteraemia and guide Rx</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 16 year old girl with an exacerbation of anorexia nervosa has been referred by her local doctor for a medical admission.","parts":[{"id":"a","label":"Part A","prompt":"List 5 criteria for admission under a medical team. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________ You have assessed the patient as requiring admission for refeeding."},{"id":"b","label":"Part B","prompt":"List 5 complications that might occur during the initial stages of refeeding. (5 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">BMI &lt;12 or &lt;75% IBW</div><div class=\"answer-line\">Systolic BP &lt;80</div><div class=\"answer-line\">HR &lt;50 or &gt;120</div><div class=\"answer-line\">Postural Tachy &gt;20bpm or Postural Hypotension &gt;20mmHg</div><div class=\"answer-line\">Temp &lt;35.5 or &gt;38</div><div class=\"answer-line\">BGL &lt;3</div><div class=\"answer-line\">Sodium &lt;125</div><div class=\"answer-line\">K &lt;3</div><div class=\"answer-line\">Hypophosphataemia</div><div class=\"answer-line\">Hypomagnesaemia</div><div class=\"answer-line\">Neutropaenia &lt;0.7</div><div class=\"answer-line\">ECG abnormalities</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypophosphataemia</div><div class=\"answer-line\">Hypokalaemia</div><div class=\"answer-line\">Congestive Cardiac Failure</div><div class=\"answer-line\">Peripheral Oedema</div><div class=\"answer-line\">Rhabdomyolysis</div><div class=\"answer-line\">Seizures</div><div class=\"answer-line\">Haemolysis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 14 year old boy has presented to the ED with a painful right hand. He injured his index finger 2 days prior while climbing a tree. The patient has type 1 diabetes mellitus. A clinical photograph of the right hand is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities in the photograph. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"List the most likely diagnosis. (1 mark)"},{"id":"c","label":"Part C","prompt":"List and justify 3 investigations you would perform. (3 marks)\nInvestigation Justification The patient’s vital signs are: Temperature 38.5 degrees Pulse /min\n\nBP\n110/75 mmHg"},{"id":"d","label":"Part D","prompt":"State 5 steps in your management of this patient. Include doses and end-points where\nrelevant. (5 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________"}],"propPages":["asset:imgc4cb5fffe538d26345"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Wound over palmar aspect DIPJ</div><div class=\"answer-line\">Erythema extending to thenar eminence</div><div class=\"answer-line\">Oedema of index finger, extending to palmar space and thenar eminence</div><div class=\"answer-line\">Flexion of index finger – consistent with tenosynovitis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Infective Tenosynovitis (do not accept cellulitis)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Imaging USS to exclude soft tissue collection requiring drainage (tendon sheath abscess)</div><div class=\"answer-line\">Wound swab m/c/s to guide therapy (ie identification of MRSA)</div><div class=\"answer-line\">BSL to guide strict glycaemic control in diabetic with stress response</div><div class=\"answer-line\">Others acceptable if well justified</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Analgesia – titrated morphine 0.1mg/kg to 5mg, repeat to comfort</div><div class=\"answer-line\">IV Fluids – age 14 – HR 90 – likely just maintenance fluid requirements – 125 mls/hr of crystalloid,</div><div class=\"answer-line\">BSL will guide dextrose or non-dextrose containing</div><div class=\"answer-line\">IV Insulin lnfusion – daily dose /24 /hr to maintain euglycaemia</div><div class=\"answer-line\">Immobilisation or elevation of affected limb – splinting</div><div class=\"answer-line\"><strong>Orthopaedics/Hand Surgery for OT for drainage </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 45 year old man with a history of alcohol abuse has presented to your department with intractable vomiting. On examination, the patient is diaphoretic with epigastric tenderness. A venous blood gas is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State your interpretation of the RESPIRATORY acid-base status and list 3 differential diagnoses. (4 marks) Interpretation (1 mark) Differential diagnoses (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"State your interpretation of the METABOLIC acid-base status, show your supporting\ncalculations and list 2 differential diagnoses. (5 marks)\nInterpretation (1 mark) Supporting calculations (2 marks) Differential diagnoses (2 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"List 4 other investigations you will perform in this patient. Provide justification for each. (4 marks) Investigation Justification"}],"propPages":["asset:img2c20c46fa9a228eb86"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/13</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Marked Respiratory Alkalosis (CO2 19)</div><div class=\"answer-line\">Differential:</div><div class=\"answer-line\">Pain</div><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Anxiety</div><div class=\"answer-line\">Sepsis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">HAGMA</div><div class=\"answer-line\">HAGMA – Anion Gap = 137 – (98 + 18) = 21</div><div class=\"answer-line\">Delta ratio 9/6 = 1.5</div><div class=\"answer-line\">(for this will accept both conclusions of pure HAGMA and possible concomitant met alkalosis from</div><div class=\"answer-line\">vomiting)</div><div class=\"answer-line\">Lactic acidosis</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Hypoperfusion</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Liver failure</div><div class=\"answer-line\">With low Ca, pancreatitis a big DDx</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>CXR</td><td>?Subdiaphragmatic free air indicating perforated viscus</td></tr><tr><td>Lipase</td><td>Evidence of pancreatitis</td></tr><tr><td>Chem20</td><td>Exclude renal failure given marked hyperlactataemia,</td></tr><tr><td>exclude evidence of fulminant hepatitis</td><td></td></tr><tr><td>COAGs</td><td>Synthetic liver failure (staging of severity of liver disease)</td></tr><tr><td>Many others likely acceptable</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"The ambulance service is transporting a 55 year old woman following an out of hospital cardiac arrest. They report the initial rhythm was PEA. Return of spontaneous circulation was achieved after 15 minutes of ALS which consisted of CPR, 3mg of adrenaline and intubation. You are preparing your team to accept this patient.","parts":[{"id":"a","label":"Part A","prompt":"With reference to the Australian Resuscitation Council (ARC) Guidelines, list 3 recommended indications for EMERGENT cardiac catheterisation in patients suffering out\n• f hospital cardiac arrest. (3 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ On arrival, the patient has the following vital signs:\n\nGCS\nPulse /min\n\nBP\n165/96 mmHg\nO2 saturation 100%\n\nFiO2 100%\nTemperature 35.5 degrees The ambulance handover describes a sudden collapse with no preceding symptoms. An ECG is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List 2 key findings from the ECG. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"State the clinical significance of the ECG findings. (2 marks) The patient has been given no sedation or paralysis and remains GCS 3. A non-contrast CT scan of her head has been performed. A slice of the patient’s CT head is provided in the PROPS BOOKLET."},{"id":"d","label":"Part D","prompt":"State the diagnosis demonstrated on the CT scan. (1 mark)"},{"id":"e","label":"Part E","prompt":"List 4 additional CT findings you would seek that would portend a poor prognosis.\n(4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ Shortly after the CT scan, the patient has become hypoxic and the ventilator is alarming due to high pressure measurement."},{"id":"f","label":"Part F","prompt":"In the table, list 5 possible causes for these problems. For each provide a supportive assessment finding (history, examination, investigation), and the key intervention required to manage the problem. (15 marks) Cause Assessment finding Key intervention"}],"propPages":["asset:img695bcf75979c7a0b25","asset:img47d184354055925173","asset:img66aa8122725b8cd727"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>19/28</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">STEMI preceding cardiac arrest</div><div class=\"answer-line\">STEMI on post-ROSC ECG</div><div class=\"answer-line\">New LBBB on post ROSC ECG</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">widespread ST depression</div><div class=\"answer-line\">ST Elevation in aVR</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Global ischaemia – likely secondary to prolonged arrest</div><div class=\"answer-line\">(note: not consistent with LMCO given absence of cardiogenic shock)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Subarachnoid haemorrhage (Fisher IV; WFNS V given GCS 3)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Loss of grey-white differentiation</div><div class=\"answer-line\">Tonsillar herniation</div><div class=\"answer-line\">Obstructive Hydrocephalus</div><div class=\"answer-line\">Loss of sulci - increased pressure/diffuse oedema</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Tube displacement – RMB intubation on CXR – relocate to appropriate location &gt;3cm above carina</td><td>Inadequate sedation/dyssynchrony- patient triggered breaths – increase sedation +/- paralysis</td></tr><tr><td>Bronchospasm – wheeze, hyperinflation/incomplete expiration – bronchodilator Rx (salbutamol 5mg</td><td>nebules)</td></tr><tr><td>Tube obstruction – no chest expansion, inability to bag, pass suction catheter- suction or change</td><td>tube</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 52 year old man has presented after rolling his quadbike. He is conscious but complains of severe right-sided chest pain. Your assessment, including a CT scan, has revealed fractured ribs 5 - 10 on the right side with a small pneumothorax. His only other injury is a closed ankle fracture which has been placed in a plaster backslab.","parts":[{"id":"a","label":"Part A","prompt":"List 3 indications for the insertion of an intercostal catheter (ICC) in this patient. (3 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ You have decided that ICC insertion is not currently warranted. You are completing the admission of the patient directly to a surgical unit for review on the ward in\nthe next 4 hours."},{"id":"b","label":"Part B","prompt":"State 4 analgesic options, including doses, that you could use. For each, indicate 1 contra- indication to its use, NOT including allergy. (8 marks) Analgesic option with dose Contra-indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hypoxia</div><div class=\"answer-line\">Ventilatory failure requiring Positive Pressure Ventilation (either NIV or Intubation)</div><div class=\"answer-line\">Need for operative intervention (eg ankle operation)</div><div class=\"answer-line\">Progressive pneumothorax or development of haemothorax</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Morphine (or other) PCA ie 1mg bolus, 5 min lockout C/I: Severe renal failure, hypercapnoea</td><td>NSAIDS; ibuprofen 400mg tds: C/I: Renal Impairment</td></tr><tr><td>Paracetamol 1g QID – chronic liver disease</td><td>Oxycodone 5mg prn – oversedation from other opiates eg PCA</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 35 year old man has been brought to your ED after collapsing during a half-marathon. His\ntemperature is 41 degrees.\nYour provisional diagnosis is of heat stroke.","parts":[{"id":"a","label":"Part A","prompt":"List 4 early complications of heat stroke. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 invasive measures you might use to cool this patient. State the clinical indication for each method. (8 marks) Invasive measure Clinical indication"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hypotension</div><div class=\"answer-line\">Rhabdomyolysis</div><div class=\"answer-line\">Coma</div><div class=\"answer-line\">Seizure</div><div class=\"answer-line\">Pulmonary Oedema</div><div class=\"answer-line\">Renal failure</div><div class=\"answer-line\">Hyper/Hyponatraemia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cold IV Fluids (ie 4deg saline)</td><td>first line invasive, use if not invasive methods insufficient</td></tr><tr><td>Cold water bladder lavage</td><td>unconscious, intubated, has IDC suitable for lavage</td></tr><tr><td>Intubation and paralysis</td><td>coma with shivering</td></tr><tr><td>ECMO</td><td>unresponsive shock / arrested patient</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 20 year old man has presented with chest pain and difficulty breathing. He has no known medical problems. His chest x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give the diagnosis. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 2 supportive radiographical abnormalities. (2 marks)"},{"id":"c","label":"Part C","prompt":"List 3 possible treatment options for this man. State the clinical circumstance in which you would use each option. (6 marks) Treatment option Appropriate clinical circumstance"}],"propPages":["asset:imgf8935ae02706d58136"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/9</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left sided pneumothorax</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Visible lung edge</div><div class=\"answer-line\">Absence of lung markings at left apex</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Observation +/- with high-flow O2 and repeat CXR</td></tr><tr><td>-</td><td>Stable patient</td></tr><tr><td>-</td><td>Minimal pain</td></tr><tr><td>-</td><td>Close follow up</td></tr><tr><td>-</td><td>Responds well to simple analgesia</td></tr><tr><td colspan=\"2\">Needle Aspiration</td></tr><tr><td>-</td><td>Progression/ failure of conservative Rx</td></tr><tr><td>-</td><td>Pain refractory to simple analgesia</td></tr><tr><td colspan=\"2\">Small bore ICC insertion/ Pleurocath</td></tr><tr><td>-</td><td>Hypoxia</td></tr><tr><td>-</td><td>Increasing size pneumothorax</td></tr><tr><td>-</td><td>Recurrent primary pneumothorax</td></tr><tr><td colspan=\"2\">Primary VATS / pleurodesis</td></tr><tr><td>-</td><td>Access to appropriate speciality</td></tr><tr><td>-</td><td>Work related requirement – eg pilot</td></tr><tr><td>-</td><td>Recurrent PTx</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 27 year old man has presented to ED one hour after being bitten by a snake on his right hand. He is complaining of pain at the bite site. A pressure immobilisation bandage (PIB) has been applied.","parts":[{"id":"a","label":"Part A","prompt":"List 4 conditions that must be met for removal of the PIB. (4 marks)\nThe patient is complaining of double vision in all directions of gaze. A clinical photograph is provided in the PROPS BOOKLET."},{"id":"b","label":"Part B","prompt":"List 2 significant abnormalities demonstrated. (2 marks)"},{"id":"c","label":"Part C","prompt":"What is the diagnosis? (2 marks)"},{"id":"d","label":"Part D","prompt":"List 3 species of snakes that might cause this clinical picture. (3 marks)"}],"propPages":["asset:imgddc9c2d1c03738aa90"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">No clinical signs of envenoming</div><div class=\"answer-line\">No lab signs of envenoming</div><div class=\"answer-line\">Patient in monitored, witnessed area</div><div class=\"answer-line\">Local access to antivenom</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Ptosis R eye</div><div class=\"answer-line\">Lateral deviation of Rt eye</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Rt 3rd CN palsy indicating neurotoxicity</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Tiger</div><div class=\"answer-line\">Taipan</div><div class=\"answer-line\">Death Adder</div><div class=\"answer-line\">(sea snakes)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 2 year old girl has been brought to the ED after having a seizure at home.","parts":[{"id":"a","label":"Part A","prompt":"List 4 criteria necessary for the diagnosis of simple febrile convulsion. (4 marks)\nYour assessment is of a simple febrile convulsion. No clear source of the fever has been identified."},{"id":"b","label":"Part B","prompt":"List 4 investigations you might perform. Include the clinical indication for each\ninvestigation. (4 marks) Investigation Clinical indication Following a brief period of observation, the child’s mother has asked to take her daughter home."},{"id":"c","label":"Part C","prompt":"List 4 conditions that would need to be met to allow safe discharge. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Generalised (not focal)</div><div class=\"answer-line\">Less than 15 mins in duration</div><div class=\"answer-line\">No more than one in 24 hours</div><div class=\"answer-line\">Neurologically normal post ictal</div><div class=\"answer-line\">Developmentally normal child</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Blood Culture</td><td>Signs of sepsis/ toxicity</td></tr><tr><td>CXR</td><td>Focal findings concerning for LRTI or Hx of aspiration during</td></tr><tr><td>seizure</td><td></td></tr><tr><td>Lumbar Puncture</td><td>Clinical features of CNS infection – meningism, confusion</td></tr><tr><td>Urine</td><td>common cause fever in 2yo girl, mandatory this patient</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Clear plan for follow up</div><div class=\"answer-line\">Ability to access health care urgently in case of deterioration</div><div class=\"answer-line\">Has safe means of getting home</div><div class=\"answer-line\">Parental understanding of condition and when to seek review</div><div class=\"answer-line\">Parental understanding of long-term implications of febrile seizure</div><div class=\"answer-line\">Parental plan for first-aid in event of recurrence</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 3 week old boy has been taken to hospital by her mother. The mother is concerned that the child will not stop crying.","parts":[{"id":"a","label":"Part A","prompt":"List 5 findings on history that would indicate the need for further investigation. (5 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ The child’s vital signs are within normal limits."},{"id":"b","label":"Part B","prompt":"List 6 examination findings that you would seek to identify. Explain the relevance of each. (6 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ 5) ________________________________________________________________________________ 6) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Failure to achieve birth weight/ gain weight</div><div class=\"answer-line\">History of fevers</div><div class=\"answer-line\">Not waking for feeds</div><div class=\"answer-line\">Bilious vomiting</div><div class=\"answer-line\">Absence of/abnormal bowel motions</div><div class=\"answer-line\">Inability to effectively feed</div><div class=\"answer-line\">Lots of others….</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Bulging fontanelle – suggests raised ICP – diff includes hydrocephalus, intraventricular haemorrhage,</div><div class=\"answer-line\">CNS infection</div><div class=\"answer-line\">Hepatomegaly – suggests possible congenital heart disease with CCF</div><div class=\"answer-line\">Jaundice – suggests metabolic syndrome or structural hepatobiliary disease</div><div class=\"answer-line\">Hernias – may indicate bowel involvement</div><div class=\"answer-line\">Bruising – suggess haematologic disorder or possible abuse</div><div class=\"answer-line\">Other signs abuse – eg philtrum</div><div class=\"answer-line\">Fingers / toes / penis for hair tourniquet</div><div class=\"answer-line\">Eyes – corneal injury</div><div class=\"answer-line\">Many others OK if relevance explained</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 35 year old woman has presented to the ED with a rash over her trunk and arms.\nA clinical photograph has been provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 3 descriptive features of the rash. (3 marks)\nYour registrar has suggested that the diagnosis might be erythema multiforme."},{"id":"b","label":"Part B","prompt":"List 3 possible causes of erythema multiforme. (3 marks)"},{"id":"c","label":"Part C","prompt":"List 3 differential diagnoses. For each, state an important feature of your overall\nassessment (history, examination, investigation) that would support the diagnosis. (6 marks) Differential diagnosis Assessment feature"}],"propPages":["asset:img55a9000d840fe66f67"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Macular rash</div><div class=\"answer-line\">Discrete erythematous lesions of multiple sizes</div><div class=\"answer-line\">Target lesions</div><div class=\"answer-line\">Involving palms</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Infectious – Mycoplasma, HSV</div><div class=\"answer-line\">Malignancy</div><div class=\"answer-line\">Drugs – Antibiotics (Cephalosporins, Erythromycin)</div><div class=\"answer-line\">Anticonvulsants (Carbamazepine)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Syphilis – serology, primary chancre, secondary generalised rash</td><td>Gonococcaemia – Hx unprotected sex, vagnial discharge, symptoms PID, urine PCR</td></tr><tr><td>Hand, Foot and Mouth (Coxsackie) – mouth lesions, sole foot lesions, contact with others with</td><td>disease</td></tr><tr><td>Others might be OK</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 50 year old woman has presented with a painful, red left eye.","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnoses. For each, give a cardinal examination finding that would\nsupport the diagnosis. (10 marks) Diagnosis Cardinal examination finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Iritis</td><td>Perilimbic Inflamm, Cells and Flare in ant chamber, synechiae</td></tr><tr><td>Glaucoma</td><td>Raised IOP</td></tr><tr><td>Corneal Abrasion</td><td>Defect with fluorescin uptake on slit lamp</td></tr><tr><td>Dendritic Ulcer</td><td>Dendritic Ulcer on Slit Lamp</td></tr><tr><td>Infective Conjunctivitis</td><td>Discharge, conjunctival erythema,</td></tr><tr><td>Episcleritis/Scleritis</td><td>Diffuse or sectoral inflammation</td></tr><tr><td>Allergic conjunctivitis</td><td>cobblestone appearance to lid conjuctiva</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"The ambulance service has notified you of a 22 year old man who has been stabbed multiple times to the back with a kitchen knife. He will be arriving to your ED in approximately 10 minutes.\nHis vital signs on scene are:\n\nGCS\nPulse 125 /min\n\nBP\n95/45 mmHg\n\nRR\n/min O2 sats 99% 15L/min O2 via non-breather","parts":[{"id":"a","label":"Part A","prompt":"List 5 life-threatening injuries that you will aim to identify on the patient’s arrival. For each injury, state how you will confirm its presence and the action you will take to manage the condition. (15 marks)\nInjury 1\nConfirmation Management\nInjury 2\nConfirmation Management\nInjury 3\nConfirmation Management\nInjury 4\nConfirmation Management\nInjury 5\nConfirmation Management During the early management of this patient in the ED, you have identified uncontrolled massive haemorrhage. As such, the hospital’s massive transfusion protocol has been activated."},{"id":"b","label":"Part B","prompt":"State 4 principles of your fluid resuscitation of this patient. Include end-points where\nappropriate. (4 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>14/19</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Confirmation: CXR/E-FAST/Clinical signs</td><td>Management: Decompression with ICC placement</td></tr><tr><td>Injury: Massive Haemothorax</td><td>Confirmation: CXR</td></tr><tr><td>Management: Decompression with ICC, Volume resuscitation</td><td>Injury: Cardiac Tamponade</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Blood Only</div><div class=\"answer-line\">Matched components 1:1:1 PRBCs:Plts:FFP</div><div class=\"answer-line\">Aim for maintenance of cerebral perfusion, SBP approx. 80</div><div class=\"answer-line\">Identify and correct Trauma Induced Coagulopathy (ie ROTEM guided fibrinogen replacement)</div><div class=\"answer-line\">TXA</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 5 year old girl has been brought to the ED with a 3 day history of vomiting, diarrhea and lethargy. A full blood count is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Interpret the results, including a likely diagnosis. (2 marks)"},{"id":"b","label":"Part B","prompt":"List and justify 5 additional investigations you would perform. (10 marks)"}],"propPages":["asset:img408d2aaa11a718c064"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>6/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Evidence of anaemia with thrombocytopaenia (NOT pancytopaenia)</div><div class=\"answer-line\">Most likely cause would be HUS in this clinical setting</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Blood film – look for schistocytes to confirm haemolysis</div><div class=\"answer-line\">Blood Culture – identify sepsis as cause of HUS ie E coli</div><div class=\"answer-line\">Haptoglobin – reduced confirms haemolysis</div><div class=\"answer-line\">Chem20 – identify associated uraemia HUS</div><div class=\"answer-line\">Bilirubin / LDH – raised in haemolysis</div><div class=\"answer-line\">Lots of others – urine for haemoglobinuria</div><div class=\"answer-line\">Ultrasound abdomen for splenomegaly (diff includes hypersplenism)</div><div class=\"answer-line\">Viral serology for other causes of megakaryocyte stuff (ie parvovirus serology)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 12 month old boy has been brought to the ED by his father. The child has been unwell for 2 days with fevers and decreased oral intake. On arrival the child is blue and unresponsive. He has been rapidly transferred to the resuscitation bay. The child’s vital signs are:\n\nGCS\n\nHR\n/min\n\nBP\nnot recordable\n\nRR\nno effort","parts":[{"id":"a","label":"Part A","prompt":"State 6 specific components of your initial management. (6 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________ 6)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"State 2 potential benefits of parental presence during the resuscitation. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________"},{"id":"c","label":"Part C","prompt":"State 2 potential disadvantages of parental presence during the resuscitation. (2 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/10</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Apply 100% O2 via BVM / intubate OK</div><div class=\"answer-line\">IV access and fluid bolus O.9% saline 20ml/kg (or similar) (200ml)</div><div class=\"answer-line\"><strong>IV adrenaline 10mcg/kg (12 month old approx. 10kg – accept 100mcg) </strong></div><div class=\"answer-line\">Seek and treat hypoglycaemia with IV 5ml/kg 10% dextrose (ie 50ml 10%)</div><div class=\"answer-line\">IV antibiotics OK – ceftriaxone / cefotaxime – 50-100/kg</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Allows parent to see all treatment being provided</div><div class=\"answer-line\">In case of unsuccessful resuscitation, allows initiation of grieving process</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Can worsen staff grief around events of highly emotive resuscitation</td><td>Potential for interference with resuscitation from parents unless dedicated staff member caring for</td><td>parent</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 55 year old woman has self-presented to your tertiary ED with central chest pain for the last 2 hours. Her past medical history includes hypertension and hyperlipidaemia. Her ECG is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"List 4 abnormalities on the ECG. (4 marks)\n1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________"},{"id":"b","label":"Part B","prompt":"Give your diagnosis. (2 marks) The patient’s vital signs are:\n\nGCS\n\nBP\n75/45 mmHg\n\nRR\n/min O2 sats 98% room air"},{"id":"c","label":"Part C","prompt":"State 6 steps in your management of this patient. Include doses and end-points where\nappropriate. (6 marks) 1)________________________________________________________________________________ 2)________________________________________________________________________________ 3)________________________________________________________________________________ 4)________________________________________________________________________________ 5)________________________________________________________________________________ 6)________________________________________________________________________________"}],"propPages":["asset:img0dcd2602b280828331"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Note rate currently 78/min – chronotherapy not currently indicated</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Inferoposterior STEMI with RV involvement</div><div class=\"answer-line\">Meets criteria for reperfusion</div><div class=\"answer-line\">3.</div><div class=\"answer-line\"><strong>Aspirin 300mg PO </strong></div><div class=\"answer-line\">Fluid load 10-20ml/kg aiming SBP &gt;100 or MAP &gt;65</div><div class=\"answer-line\">Second antiplatelet in appropriate dose</div><div class=\"answer-line\">Heparin load (5000u or similar) + bolus</div><div class=\"answer-line\">Analgesia Fentanyl 25mcg repeat to comfort</div><div class=\"answer-line\"><strong>Activate cath lab </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Note rate currently 78/min – chronotherapy not currently indicated</div><div class=\"answer-line\">Fail – if gives GTN</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 35 year old man has re-presented with a painful left foot. He was seen 2 days prior in your ED after falling off a skateboard. He was discharged with a diagnosis of “ankle sprain” and advised to\n\nweight bear as tolerated.\nHis x-ray is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"State the injury demonstrated on the x-ray. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 3 possible complications of this injury. (3 marks)\nYou have explained the missed diagnosis to the patient and reassured him that you will perform a root cause analysis as part of your management."},{"id":"c","label":"Part C","prompt":"Complete the table by listing 6 potential causes of this error. Provide a solution for each potential cause. (12 marks) Category Cause Solution Systems issues Process issues Individual issues"}],"propPages":["asset:img3891df04a0e69612b5"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>10/16</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left foot ‘Lisfranc’ injury (widening of space between 1st and 2nd metatarsal base)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lateral dislocation of midfoot</div><div class=\"answer-line\">Compartment syndrome of foot</div><div class=\"answer-line\">Early OA and non-union/loss of function</div><div class=\"answer-line\">Loss of arch – inability to walk</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>System – STRUCTURE ie staffing/work areas/ specialty support</td><td></td></tr><tr><td>-</td><td>Inadequate senior staff numbers to provide supervision</td></tr><tr><td>-</td><td>Poor training of supervising staff regarding common missed injuries</td></tr><tr><td>-</td><td>Lack of on-site or timely radiology review</td></tr><tr><td>Process – Workflow and supervision/rostering; process and protocol</td><td></td></tr><tr><td>-</td><td>Policy regarding senior review prior to all discharge</td></tr><tr><td>-</td><td>Policy regarding senior review of all xrays prior to review</td></tr><tr><td>-</td><td>Lack of notification from radiology of abnormal reports</td></tr><tr><td>-</td><td>Lack of education for junior staff</td></tr><tr><td>Individual- Junior doctor specific issues</td><td></td></tr><tr><td>-</td><td>Lack of awareness around training</td></tr><tr><td>-</td><td>Performance issues (ie professional concerns around self-care, MH etc)</td></tr><tr><td>-</td><td>Not following/adhering to local protocols around supervision/seeking review etc</td></tr><tr><td>Solutions – anything sensible directly addressing the stated cause</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"You have been asked to develop a protocol for the direct admission of patients with suspected acute coronary syndrome to a cardiology ward for further review by a cardiologist.","parts":[{"id":"a","label":"Part A","prompt":"List 3 criteria for admission to a monitored bed. (3 marks)"},{"id":"b","label":"Part B","prompt":"List 4 criteria that would need to be satisfied before the patient leaves the ED. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________ One month after institution of the process, you have been approached by a cardiologist regarding a patient who was found to have a diagnosis of pancreatitis after being admitted to a cardiology ward."},{"id":"c","label":"Part C","prompt":"List 4 key components of your management of this issue. (4 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>7/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">ECG changes – ST segment elevation of depression</div><div class=\"answer-line\">Positive troponin</div><div class=\"answer-line\">Recurrent unstable pain</div><div class=\"answer-line\">Ongoing tachyarrhythmia (ie rapid AF) for active management (ie infusions)</div><div class=\"answer-line\">Syncope of suspected electrophysiological origin</div><div class=\"answer-line\">Resolved malignant arrhythmia (ie VT)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Clear documentation from ED documenting decision making and rationale</div><div class=\"answer-line\">Patient understanding and awareness of plan</div><div class=\"answer-line\">Basic investigations initiated</div><div class=\"answer-line\">Clinical safe parameters (vital signs, pain etc)</div><div class=\"answer-line\">Medications charted for next 4 hours (including prns)</div><div class=\"answer-line\">Indications of triggers mandating urgent review</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Thank them for feedback</div><div class=\"answer-line\">Pledge to investigate; feedback</div><div class=\"answer-line\">Audit of some type – review error rate to determine if there is a problem with system</div><div class=\"answer-line\">Review case documentation</div><div class=\"answer-line\">Discuss case with staff involved</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 24 year old man has presented with a fever. He had chemotherapy 6 days ago for treatment of a testicular malignancy. His full blood count is provided in the PROPS BOOKLET.","parts":[{"id":"a","label":"Part A","prompt":"Give your interpretation of the results. (2 marks) On examination, the patient has erythema around the insertion site of a PICC line."},{"id":"b","label":"Part B","prompt":"List and justify 3 antibiotics you will use. Include doses. (6 marks)\nAntibiotic Justification"},{"id":"c","label":"Part C","prompt":"List 3 indications for removal of the PICC line in the ED. (3 marks)\n1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________"}],"propPages":["asset:img41900d22b29114443b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>8/11</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Evidence of pancytopaenia and leukopaenia implying severe (marked) neutropaenia</div><div class=\"answer-line\">In context of patient presentation is consistent with febrile neutropaenia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Piperacillin/Tazobactam 4.5gm – broad spectrum Ab with gram +ve /-ve AND anaerobic cover</td></tr><tr><td>-</td><td>Will cover staph, pneumococcus and intestinal organisms as well as pseudomonas</td></tr><tr><td colspan=\"2\">Gentamicin 5mg/kg (or similar) – gram neg cover</td></tr><tr><td>-</td><td>Will cover gram negs including E. Coli, Pseudomonas</td></tr><tr><td colspan=\"2\">Vancomycin 30mg/kg</td></tr><tr><td>-</td><td>Will cover MRSA/MSSA from in-dwelling line</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Clear infection at PICC site (surrounding skin or pus on aspiration)</div><div class=\"answer-line\">PICC line displacement (ie line partially removed)</div><div class=\"answer-line\">Leaking/fractured line</div><div class=\"answer-line\">Cultures from PICC +ve &gt;2 hrs earlier than systemic cultures</div><div class=\"answer-line\">severe sepsis/ shock with clinical suspicion of line infection</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"You are managing a 54 year old man with a dislocated elbow. Your plan is to reduce the dislocation under procedural sedation.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your examination that would suggest a potential difficulty with bag-\nvalve-mask ventilation. (4 marks)"},{"id":"b","label":"Part B","prompt":"List 4 features of your examination that would suggest a potential difficulty with\nlaryngoscopy. (4 marks) During the procedure, the patient becomes apnoeic. Your initial attempts to ventilate the patient via bag-valve-mask have been unsuccessful."},{"id":"c","label":"Part C","prompt":"List 4 interventions you might perform in managing this man’s airway. Provide the\nindication for each intervention. (4 marks) 1) ________________________________________________________________________________ 2) ________________________________________________________________________________ 3) ________________________________________________________________________________ 4) ________________________________________________________________________________"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Edentulous patient</div><div class=\"answer-line\">Facial dysmorphism</div><div class=\"answer-line\">Beard/Facial Hair</div><div class=\"answer-line\">Obese</div><div class=\"answer-line\">Snoring/Sleep Apnoea History</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Mallampati score II/IV</div><div class=\"answer-line\">3-3-2 rule (short in any of these)</div><div class=\"answer-line\">Upper Airway Obstruction</div><div class=\"answer-line\">Impaired Neck Mobility</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Optimise positioning – elevate occiput with pillow – indication: hyperextension/flexion leading to</td><td>possible upper airway obstruction</td></tr><tr><td>Two-person technique – indication – inadequate seal/leak with one-person BVM</td><td>Oropharyngeal/Nasopharyngeal adjunct – suspected upper airway obstruction from oedematous or</td></tr><tr><td>just large soft tissues</td><td>Sedation (ie Propofol) – laryngospasm</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 60 year old man has presented to the ED with severe epigastric abdominal pain.","parts":[{"id":"a","label":"Part A","prompt":"List 4 serious differential diagnoses. For each diagnosis, state the supportive findings on abdominal examination and a key finding on investigation. (12 marks) Diagnosis Findings on abdominal Key finding on investigation examination"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><div class=\"answer-pass-mark\">Pass mark: <strong>9/12</strong></div><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Diagnosis - Pancreatitis</td><td>Findings on Exam – soft abdomen, epigastric tenderness, relieved sittingup</td></tr><tr><td>Key Investigative Finding – Elevated Lipase</td><td>Diagnosis - Acute Cholecystitis</td></tr><tr><td>Findings on Exam – Murphy’s positive / RUQ peritonism</td><td>Key Investigative Finding – Thickened GB wall (&gt;3mm) +/- pericholecystic fluid on USS</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
